using System.IO;
using Microsoft.Data.Sqlite;
using RefaccionariaDesktop.Models;
namespace RefaccionariaDesktop.Data;
public sealed class Database {
 private readonly string cs;
 public Database(){var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"RefaccionariaDesktop");Directory.CreateDirectory(dir);cs=new SqliteConnectionStringBuilder{DataSource=Path.Combine(dir,"refaccionaria.db"),ForeignKeys=true}.ToString();using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText=@"PRAGMA foreign_keys=ON;
 CREATE TABLE IF NOT EXISTS Products(Id INTEGER PRIMARY KEY AUTOINCREMENT,Code TEXT NOT NULL UNIQUE,Name TEXT NOT NULL,Category TEXT NOT NULL,Brand TEXT NOT NULL DEFAULT '',PartNumber TEXT NOT NULL DEFAULT '',Cost REAL NOT NULL DEFAULT 0,Price REAL NOT NULL DEFAULT 0,Stock INTEGER NOT NULL DEFAULT 0,MinStock INTEGER NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS Sales(Id INTEGER PRIMARY KEY AUTOINCREMENT,CreatedAt TEXT NOT NULL,Total REAL NOT NULL);
 CREATE TABLE IF NOT EXISTS SaleItems(Id INTEGER PRIMARY KEY AUTOINCREMENT,SaleId INTEGER NOT NULL REFERENCES Sales(Id),ProductId INTEGER NOT NULL REFERENCES Products(Id),Code TEXT NOT NULL,Name TEXT NOT NULL,Quantity INTEGER NOT NULL,UnitPrice REAL NOT NULL,LineTotal REAL NOT NULL);
 CREATE TABLE IF NOT EXISTS Equivalences(Id INTEGER PRIMARY KEY AUTOINCREMENT,ProductId INTEGER NOT NULL REFERENCES Products(Id) ON DELETE CASCADE,Brand TEXT NOT NULL,PartNumber TEXT NOT NULL,Notes TEXT NOT NULL DEFAULT '',UNIQUE(ProductId,Brand,PartNumber));
 CREATE TABLE IF NOT EXISTS CashClosings(Id INTEGER PRIMARY KEY AUTOINCREMENT,BusinessDate TEXT NOT NULL UNIQUE,ClosedAt TEXT NOT NULL,SalesCount INTEGER NOT NULL,Total REAL NOT NULL);";cmd.ExecuteNonQuery();}
 private SqliteConnection Open()=>new(cs);
 public List<Product> GetProducts(string? search=null){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT Id,Code,Name,Category,Brand,PartNumber,Cost,Price,Stock,MinStock FROM Products WHERE ($q='' OR Code LIKE $like OR Name LIKE $like OR PartNumber LIKE $like OR Brand LIKE $like) ORDER BY Name";var q=search?.Trim()??"";cmd.Parameters.AddWithValue("$q",q);cmd.Parameters.AddWithValue("$like","%"+q+"%");using var r=cmd.ExecuteReader();var a=new List<Product>();while(r.Read())a.Add(ReadProduct(r));return a;}
 private static Product ReadProduct(SqliteDataReader r)=>new(){Id=r.GetInt64(0),Code=r.GetString(1),Name=r.GetString(2),Category=r.GetString(3),Brand=r.GetString(4),PartNumber=r.GetString(5),Cost=(decimal)r.GetDouble(6),Price=(decimal)r.GetDouble(7),Stock=r.GetInt32(8),MinStock=r.GetInt32(9)};
 public void SaveProduct(Product p){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO Products(Code,Name,Category,Brand,PartNumber,Cost,Price,Stock,MinStock) VALUES($code,$name,$cat,$brand,$part,$cost,$price,$stock,$min)";Bind(cmd,p);cmd.ExecuteNonQuery();}
 public void UpdateProduct(Product p){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="UPDATE Products SET Code=$code,Name=$name,Category=$cat,Brand=$brand,PartNumber=$part,Cost=$cost,Price=$price,Stock=$stock,MinStock=$min WHERE Id=$id";Bind(cmd,p);cmd.Parameters.AddWithValue("$id",p.Id);cmd.ExecuteNonQuery();}
 private static void Bind(SqliteCommand cmd,Product p){cmd.Parameters.AddWithValue("$code",p.Code);cmd.Parameters.AddWithValue("$name",p.Name);cmd.Parameters.AddWithValue("$cat",p.Category);cmd.Parameters.AddWithValue("$brand",p.Brand);cmd.Parameters.AddWithValue("$part",p.PartNumber);cmd.Parameters.AddWithValue("$cost",p.Cost);cmd.Parameters.AddWithValue("$price",p.Price);cmd.Parameters.AddWithValue("$stock",p.Stock);cmd.Parameters.AddWithValue("$min",p.MinStock);}
 public void DeleteProduct(long id){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="DELETE FROM Products WHERE Id=$id AND NOT EXISTS(SELECT 1 FROM SaleItems WHERE ProductId=$id)";cmd.Parameters.AddWithValue("$id",id);if(cmd.ExecuteNonQuery()==0)throw new InvalidOperationException("No se puede eliminar: el producto tiene historial de ventas. Puedes dejar su existencia en cero.");}
 public List<Product> GetLowStock()=>GetProducts().Where(p=>p.Stock<=p.MinStock).ToList();
 public void AddEquivalence(long productId,string brand,string part,string notes){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO Equivalences(ProductId,Brand,PartNumber,Notes) VALUES($id,$brand,$part,$notes)";cmd.Parameters.AddWithValue("$id",productId);cmd.Parameters.AddWithValue("$brand",brand.Trim());cmd.Parameters.AddWithValue("$part",part.Trim());cmd.Parameters.AddWithValue("$notes",notes.Trim());cmd.ExecuteNonQuery();}
 public List<string> GetEquivalences(long productId){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT Brand || ' — ' || PartNumber || CASE WHEN Notes='' THEN '' ELSE ' ('||Notes||')' END FROM Equivalences WHERE ProductId=$id ORDER BY Brand,PartNumber";cmd.Parameters.AddWithValue("$id",productId);using var r=cmd.ExecuteReader();var list=new List<string>();while(r.Read())list.Add(r.GetString(0));return list;}
 public (int SalesCount,decimal Total,bool IsClosed) GetCashSummary(DateTime date){var day=date.ToString("yyyy-MM-dd");using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT COUNT(*),COALESCE(SUM(Total),0) FROM Sales WHERE substr(CreatedAt,1,10)=$day";cmd.Parameters.AddWithValue("$day",day);using var r=cmd.ExecuteReader();r.Read();var count=r.GetInt32(0);var total=(decimal)r.GetDouble(1);r.Close();using var check=c.CreateCommand();check.CommandText="SELECT EXISTS(SELECT 1 FROM CashClosings WHERE BusinessDate=$day)";check.Parameters.AddWithValue("$day",day);var closed=Convert.ToInt64(check.ExecuteScalar())==1;return(count,total,closed);}
 public void CloseCash(DateTime date){var day=date.ToString("yyyy-MM-dd");using var c=Open();c.Open();using var tx=c.BeginTransaction();using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO CashClosings(BusinessDate,ClosedAt,SalesCount,Total) SELECT $day,$closed,COUNT(*),COALESCE(SUM(Total),0) FROM Sales WHERE substr(CreatedAt,1,10)=$day";cmd.Parameters.AddWithValue("$day",day);cmd.Parameters.AddWithValue("$closed",DateTime.Now.ToString("s"));cmd.ExecuteNonQuery();tx.Commit();}
 public void CompleteSale(IReadOnlyList<(Product product,int quantity)> items){if(items.Count==0)throw new InvalidOperationException("Agrega productos.");using var c=Open();c.Open();using var tx=c.BeginTransaction();var day=DateTime.Now.ToString("yyyy-MM-dd");using(var closeCheck=c.CreateCommand()){closeCheck.Transaction=tx;closeCheck.CommandText="SELECT EXISTS(SELECT 1 FROM CashClosings WHERE BusinessDate=$day)";closeCheck.Parameters.AddWithValue("$day",day);if(Convert.ToInt64(closeCheck.ExecuteScalar())==1)throw new InvalidOperationException("La caja de hoy ya fue cerrada. No se pueden registrar más ventas en esta fecha.");}decimal total=0;var current=new List<(Product product,int quantity,decimal price)>();foreach(var(p,q)in items){if(q<1)throw new InvalidOperationException("La cantidad debe ser mayor que cero.");using var read=c.CreateCommand();read.Transaction=tx;read.CommandText="SELECT Code,Name,Stock,Price FROM Products WHERE Id=$id";read.Parameters.AddWithValue("$id",p.Id);using var rr=read.ExecuteReader();if(!rr.Read())throw new InvalidOperationException("El producto ya no existe: "+p.Name);var code=rr.GetString(0);var name=rr.GetString(1);var stock=rr.GetInt32(2);var price=(decimal)rr.GetDouble(3);rr.Close();if(q>stock)throw new InvalidOperationException("Existencia insuficiente para "+name+". Disponible: "+stock);var snapshot=new Product{Id=p.Id,Code=code,Name=name};current.Add((snapshot,q,price));total+=price*q;}using(var sale=c.CreateCommand()){sale.Transaction=tx;sale.CommandText="INSERT INTO Sales(CreatedAt,Total) VALUES($date,$total); SELECT last_insert_rowid();";sale.Parameters.AddWithValue("$date",DateTime.Now.ToString("s"));sale.Parameters.AddWithValue("$total",total);var sid=Convert.ToInt64(sale.ExecuteScalar());foreach(var(p,q,price)in current){using var update=c.CreateCommand();update.Transaction=tx;update.CommandText="UPDATE Products SET Stock=Stock-$qty WHERE Id=$pid AND Stock >= $qty";update.Parameters.AddWithValue("$qty",q);update.Parameters.AddWithValue("$pid",p.Id);if(update.ExecuteNonQuery()!=1)throw new InvalidOperationException("No se pudo actualizar la existencia de "+p.Name+". Revisa el inventario e intenta de nuevo.");using var line=c.CreateCommand();line.Transaction=tx;line.CommandText="INSERT INTO SaleItems(SaleId,ProductId,Code,Name,Quantity,UnitPrice,LineTotal) VALUES($sid,$pid,$code,$name,$qty,$price,$line)";line.Parameters.AddWithValue("$sid",sid);line.Parameters.AddWithValue("$pid",p.Id);line.Parameters.AddWithValue("$code",p.Code);line.Parameters.AddWithValue("$name",p.Name);line.Parameters.AddWithValue("$qty",q);line.Parameters.AddWithValue("$price",price);line.Parameters.AddWithValue("$line",price*q);line.ExecuteNonQuery();}}tx.Commit();}
}